if (projectDbMode && project) {
  Database.projectTransaction(
    project.id,
    project.worktree,
    (tx) => {
      const id = EventID.ascending()
      const row = tx
        .select({ seq: EventSequenceTable.seq })
        .from(EventSequenceTable)
        .where(eq(EventSequenceTable.aggregate_id, agg))
        .get()
      const seq = row?.seq != null ? row.seq + 1 : 0

      const event = { id, seq, aggregateID: agg, data }
      process(def, event, { publish })
    },
    { behavior: "immediate" },
  )
  return
}

update_md5_e3ab62e0f71b1bdf77480b9b209bb.content_md5_e3ab62e0f71b1bdf77480b9b209b:
if (projectDbMode && project) {
  const projector = projectorFor(def)
  let sequence = -1
  Database.projectTransaction(
    project.id,
    project.worktree,
    (tx) => {
      const id = EventID.ascending()
      const row = tx
        .select({ seq: EventSequenceTable.seq })
        .from(EventSequenceTable)
        .where(eq(EventSequenceTable.aggregate_id, agg))
        .get()
      const seq = row?.seq != null ? row.seq + 1 : 0
      sequence = seq

      const event = { id, seq, aggregateID: agg, data }
      applyProjectEvent(tx, projector, def, event, { publish })
    },
    { behavior: "immediate" },
  )
  writeGlobalSequence(agg, sequence)
  return
}

